with filtered as (select id, carrier, shipped_date, cost, last_day(shipped_date) as shipped_date_month_end from shipments where shipped_date > date '2023-06-23' and carrier is not null) select id, carrier, shipped_date from (select *, row_number() over (partition by carrier order by shipped_date_month_end desc nulls last, id asc) as latest_rank from filtered) t where latest_rank = 1;
